    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "This systematic review assesses the scientific evidence regarding the effectiveness of organisational-level workplace mental health interventions on stress, burnout, non-clinical depressive and anxiety symptoms, and wellbeing in construction workers.",
      "reason": "Key information about the review objective and target (construction workers) and outcomes is provided, but this information appears in the abstract/objectives text rather than the title itself."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence contains no information about supplementary title details such as analysis method, included study designs, update status, or living-review status."
    }
  ],
  "confidence": 62
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "With strict inclusion criteria for the methodological quality of the individual studies, the low number of papers included in this review does not reflect the multitude of initiatives and programmes established in practice. However, some programmes appear to lack robust scientific evaluation.",
      "reason": "The manuscript describes limitations in the existing evidence base (e.g., low number of studies and limited robustness), but it does not clearly articulate the full current state of knowledge and key uncertainties in a consolidated rationale section."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "This review identified a low number of studies on this topic with only one study of moderate methodological quality showing a substantial but non-significant decline in sick leave days [73] and no significant effect on general mental health.",
      "reason": "The manuscript provides evidence of gaps/limitations in what is currently known (few studies and limited/modest effects), which indirectly supports the need for the review, but the importance/need for conducting the review is not explicitly explained in the provided evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not describe prior similar systematic reviews or explain how this review updates/replicates them."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit brief description of a proposed mechanism of action of the interventions is provided in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although the manuscript discusses the need for theoretical models/programme theory in future research (not a logic model presented for the review), the retrieved evidence does not show a logic model hypothesising relationships between intervention components and outcomes."
    }
  ],
  "confidence": 58
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The specific review questions are: (1) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms, and in enhancing mental wellbeing in construction workers? (2) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms and in enhancing mental wellbeing in SME construction workers?",
      "reason": "The review provides explicit stated review questions (objectives) in question form covering the effectiveness outcomes in construction workers and SME construction workers."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No planned intervention comparisons are stated using PICO (or an appropriate variant) in the retrieved evidence."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "Studies were included if they reported organisational-level mental health promotion interventions targeted at workers and/or managers within construction companies. In a staged approach only studies with a control group and with a before- and at least one after measurement post intervention were deemed eligible in the first round of selection as they provide the most robust evidence.",
      "reason": "Eligibility characteristics are specified for key components (population and intervention at organisational level; eligible study designs; and a follow-up requirement of at least one after measurement post intervention). However, not all study characteristics required by the criterion (e.g., explicitly stated setting requirements) are evidenced in the retrieved text."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Eligibility criteria were randomized controlled trials (RCTs), cluster randomized controlled trials (cRCTs), controlled or uncontrolled before- and after studies published in peer-reviewed journals between 2010 and May 2022",
      "reason": "Report characteristics are specified for publication status (peer-reviewed journals) and dissemination period (between 2010 and May 2022)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "included studies published in English between January 2010 and May 2022",
      "reason": "Language (English) is specified, but this excerpt does not separately clarify publication/report status beyond the language restriction."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Unpublished 'grey literature' was not included.",
      "reason": "Publication/report status is specified by excluding unpublished grey literature."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not report a distinction between exclusions due to outcomes not being measured versus exclusions due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence provides inclusion/exclusion and study characteristics, but does not specify the groups used in each synthesis or link them to the review objective comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "In a staged approach only studies with a control group and with a before- and at least one after measurement post intervention were deemed eligible in the first round of selection as they provide the most robust evidence.",
      "reason": "A rationale is provided for a notable eligibility restriction (the staged approach, selecting studies with control groups and before/after measurements in round one for robustness). However, the retrieved evidence does not comprehensively provide rationales for other notable restrictions."
    }
  ],
  "confidence": 62
}

